namespace PriceCalculatorDemo;

public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        if (unitPrice < 0) throw new ArgumentOutOfRangeException(nameof(unitPrice));
        if (quantity < 0) throw new ArgumentOutOfRangeException(nameof(quantity));

        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal total, decimal discountPercent)
    {
        if (total < 0) throw new ArgumentOutOfRangeException(nameof(total));
        if (discountPercent < 0 || discountPercent > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));

        return total * (1 - discountPercent / 100m);
    }
}

using System.Reflection;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using PriceCalculatorDemo;

namespace PriceCalculatorDemo.Tests;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ──────────────────────────────────────────────
    // CalculateTotal – DataRow (inline compile-time data)
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(5.50, 3, 16.50, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.00, DisplayName = "Zero quantity")]
    [DataRow(0.01, 100, 1.00, DisplayName = "Small price large quantity")]
    public void CalculateTotal_ReturnsExpectedResult(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1)]
    [DataRow(10.00, -1)]
    public void CalculateTotal_InvalidInput_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    // ──────────────────────────────────────────────
    // ApplyDiscount – DynamicData (complex/computed test cases)
    // ──────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountTestCases =>
    [
        [100.00m, 0m,   100.00m],  // No discount
        [100.00m, 10m,  90.00m],   // 10% off
        [100.00m, 50m,  50.00m],   // Half price
        [100.00m, 100m, 0.00m],    // Free (100% off)
        [49.99m,  25m,  37.4925m], // Fractional result
        [0.00m,   50m,  0.00m],    // Zero total
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases))]
    public void ApplyDiscount_ReturnsExpectedResult(
        decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // DynamicData from a method – useful when data requires computation
    public static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return [-1.00m, 10m, "negative total"];
        yield return [100.00m, -1m, "negative discount"];
        yield return [100.00m, 101m, "discount over 100%"];
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidInput_Throws(
        decimal total, decimal discountPercent, string scenario)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(total, discountPercent),
            $"Expected exception for scenario: {scenario}");
    }
}

